css:
.evidencesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #16313a;
    background: linear-gradient(160deg, #eef5f7 0%, #e3eef2 100%);
    border-radius: 18px;
}

.evidencesim-container * {
    box-sizing: border-box;
}

.evidencesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0b3d57 0%, #115e75 55%, #1f8a93 100%);
    color: #f2fafb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(11, 61, 87, 0.30);
}

.evidencesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.evidencesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #bfe9ee;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.evidencesim-subtitle {
    margin: 0 auto;
    max-width: 780px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dff1f4;
}

.evidencesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #134c5e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.evidencesim-period-counter #currentDay,
.evidencesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0b3d57;
}

.evidencesim-round-name {
    background: #d6ebf0;
    color: #0b3d57;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.evidencesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a23b1e;
    background: #fbe6df;
    padding: 4px 12px;
    border-radius: 999px;
}

.evidencesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.evidencesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d8e6ea;
    box-shadow: 0 4px 14px rgba(11, 61, 87, 0.06);
    border-top: 4px solid #1f8a93;
}

.evidencesim-card-compliance { border-top-color: #0b6e4f; }
.evidencesim-card-adoption { border-top-color: #2f6fb0; }
.evidencesim-card-sustain { border-top-color: #6a4fb0; }
.evidencesim-card-champion { border-top-color: #c98a16; }

.evidencesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5a7682;
}

.evidencesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0b3d57;
}

.evidencesim-card-compliance .evidencesim-value { color: #0b6e4f; }
.evidencesim-card-adoption .evidencesim-value { color: #2f6fb0; }
.evidencesim-card-sustain .evidencesim-value { color: #6a4fb0; }
.evidencesim-card-champion .evidencesim-value { color: #c98a16; }

.evidencesim-sublabel {
    font-size: 0.76rem;
    color: #6d8893;
    line-height: 1.35;
}

.evidencesim-compliance-fail .evidencesim-value { color: #c0392b; }
.evidencesim-compliance-target .evidencesim-value { color: #0b6e4f; }

.evidencesim-champion-over { border-top-color: #c0392b; }
.evidencesim-champion-over .evidencesim-value { color: #c0392b; }

.evidencesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0b3d57;
    color: #eaf6f8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.evidencesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.evidencesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1f8a93;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(11, 61, 87, 0.05);
}

.evidencesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.evidencesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0b3d57;
    margin-bottom: 6px;
}

.evidencesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2b4853;
}

.evidencesim-briefing-text strong { color: #0b6e4f; }
.evidencesim-briefing-text em { color: #a23b1e; font-style: italic; }

.evidencesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d8e6ea;
    box-shadow: 0 4px 14px rgba(11, 61, 87, 0.06);
}

.evidencesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0b3d57;
    border-bottom: 2px solid #e3eef2;
    padding-bottom: 8px;
}

.evidencesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #1c4150;
    margin: 14px 0 6px;
}

.evidencesim-container select,
.evidencesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b9d2da;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fbfc;
    color: #16313a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.evidencesim-container select:focus,
.evidencesim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f8a93;
    box-shadow: 0 0 0 3px rgba(31, 138, 147, 0.15);
}

.evidencesim-container select option {
    background-color: #ffffff;
    color: #16313a;
}

.evidencesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f8a93;
}

.evidencesim-range-readout,
.evidencesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #115e75;
    margin-top: 4px;
}

.evidencesim-range-readout span:last-child,
.evidencesim-alloc-readout span:nth-child(2) {
    color: #0b6e4f;
    font-weight: 800;
}

.evidencesim-hint {
    font-size: 0.8rem;
    color: #6d8893;
    margin-top: 4px;
    line-height: 1.4;
}

.evidencesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.evidencesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f9fa;
    border: 1px solid #dcebee;
    border-radius: 9px;
    padding: 8px 12px;
}

.evidencesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #1c4150;
}

.evidencesim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.evidencesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.evidencesim-container .btn-primary {
    background: linear-gradient(135deg, #0b6e4f 0%, #1f8a93 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(11, 110, 79, 0.28);
}

.evidencesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.evidencesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b9d2da;
    color: #5a7682;
}

.evidencesim-coach {
    background: #0b3d57;
    color: #eaf6f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(11, 61, 87, 0.22);
}

.evidencesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #87ccd4;
    margin-bottom: 8px;
}

.evidencesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.evidencesim-coach-body strong { color: #ffd98a; }
.evidencesim-coach-body em { color: #ffc1ad; font-style: italic; }

.evidencesim-history,
.evidencesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d8e6ea;
    box-shadow: 0 4px 14px rgba(11, 61, 87, 0.06);
}

.evidencesim-history h3,
.evidencesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0b3d57;
}

.evidencesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #1c4150;
}

.evidencesim-container table#usfHistoryTable th {
    background: #eaf3f5;
    color: #0b3d57;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6ea;
}

.evidencesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4f6;
}

.evidencesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbfc;
}

.evidencesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .evidencesim-container {
        padding: 14px;
    }
    .evidencesim-header h1 {
        font-size: 1.7rem;
    }
    .evidencesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .evidencesim-value {
        font-size: 2rem;
    }
    .evidencesim-clock {
        margin-left: 0;
    }
    .evidencesim-period-counter {
        font-size: 0.88rem;
    }
    .evidencesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .evidencesim-alloc-row {
        flex-wrap: wrap;
    }
    .evidencesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .evidencesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.ev-completion { padding: 8px 4px 4px; }
.ev-cm-head { text-align: center; margin-bottom: 16px; }
.ev-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f8a93; }
.ev-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b8894; }
.ev-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #16313a; }
.ev-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.ev-cm-yes { background: rgba(31,138,147,0.15); color: #167a83; border: 1px solid rgba(31,138,147,0.42); }
.ev-cm-no { background: rgba(200,70,60,0.12); color: #c0392b; border: 1px solid rgba(200,70,60,0.4); }
.ev-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.ev-cm-metric { flex: 1 1 130px; min-width: 116px; background: #f2fafb; border: 1px solid #bfe9ee; border-radius: 10px; padding: 10px 8px; text-align: center; }
.ev-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #1f8a93; }
.ev-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5b8894; text-transform: uppercase; letter-spacing: 0.03em; }
.ev-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #16313a; }
.ev-cm-insights { margin: 0; padding-left: 20px; }
.ev-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2c4a52; }

