(function() {
    'use strict';

    class EvidenceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Evidence into Practice`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_COMPLIANCE = 28;      // lapsed 2024 attempt peaked here
            this.TARGET_COMPLIANCE = 75;     // regulator day-90 trajectory
            this.NATIONAL_TARGET = 90;       // established bundle reliability
            this.BUDGET_CAP = 180;           // GBP 180k, in thousands
            this.WTE_CAP = 0.6;              // 0.6 WTE protected champion time

            // Concept truths (the adoption gap, not the evidence gap).
            this.TRUE_ROOT = `adoption`;
            this.TRUE_BARRIER = `context`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    compliance: this.START_COMPLIANCE,
                    adoption: 15,
                    sustain: 10,
                    championUsed: 0,
                    budgetUsed: 0,
                    targetMissed: false,
                    paperCompliance: false,
                    complianceHistory: [this.START_COMPLIANCE],
                    adoptionHistory: [15],
                    sustainHistory: [10],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    root: `adoption`,
                    barrier: `context`,
                    honesty: 60,
                    framing: `localdata`,
                    peer: 0.30,
                    expert: 0.15,
                    manager: 0.15,
                    artefact: `eprompt`,
                    sequence: `pilot`,
                    fidelity: `flexhow`,
                    feedback: 30,
                    protect: 60,
                    measure: `leadlag`,
                    ownership: `named`,
                    board: `honest`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const barrier = document.getElementById(`barrierInput`);
                const hon = document.getElementById(`honestyInput`);
                if (root) decisions.root = root.value;
                if (barrier) decisions.barrier = barrier.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const fr = document.getElementById(`framingInput`);
                const art = document.getElementById(`artefactInput`);
                if (fr) decisions.framing = fr.value;
                if (art) decisions.artefact = art.value;
                const peer = document.getElementById(`peerInput`);
                const expert = document.getElementById(`expertInput`);
                const manager = document.getElementById(`managerInput`);
                if (peer) decisions.peer = parseFloat(peer.value);
                if (expert) decisions.expert = parseFloat(expert.value);
                if (manager) decisions.manager = parseFloat(manager.value);
                const parts = [decisions.peer, decisions.expert, decisions.manager];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_wte_negative`); return false;
                }
                const total = Math.round((decisions.peer + decisions.expert + decisions.manager) * 100) / 100;
                if (Math.abs(total - this.WTE_CAP) > 0.001) {
                    warn(`warn_wte_total`); return false;
                }
            } else if (round === 3) {
                const seq = document.getElementById(`sequenceInput`);
                const fid = document.getElementById(`fidelityInput`);
                const fb = document.getElementById(`feedbackInput`);
                const pr = document.getElementById(`protectInput`);
                if (seq) decisions.sequence = seq.value;
                if (fid) decisions.fidelity = fid.value;
                if (fb) decisions.feedback = parseFloat(fb.value);
                if (pr) decisions.protect = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.feedback) || decisions.feedback < 0) {
                    warn(`warn_feedback_negative`); return false;
                }
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0 || decisions.protect > 100) {
                    warn(`warn_protect_range`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`measureInput`);
                const ow = document.getElementById(`ownershipInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (me) decisions.measure = me.value;
                if (ow) decisions.ownership = ow.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: adoption = genuine belief; paper = coerced compliance not backed by belief;
            // sustain = ability to survive after champion time; spend/wte = resource usage.
            let adoptionDelta = 0, sustainDelta = 0, paperDelta = 0;
            let spend = 0, wte = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the ADOPTION gap, not the evidence/training gap (Common Error 1).
                if (d.root === this.TRUE_ROOT) {
                    adoptionDelta += 16; sustainDelta += 6; coachKey = `coach_r1_root_right`;
                } else if (d.root === `training` || d.root === `knowledge`) {
                    adoptionDelta -= 8; sustainDelta -= 4; coachKey = `coach_r1_training`;
                } else {
                    adoptionDelta -= 10; sustainDelta -= 6; coachKey = `coach_r1_individuals`;
                }

                // PARiHS lens: the active role of CONTEXT is the highest-leverage barrier here.
                if (d.barrier === this.TRUE_BARRIER) {
                    adoptionDelta += 12; sustainDelta += 4;
                    if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.barrier === `facilitation`) {
                    adoptionDelta += 2;
                } else if (d.barrier === `evidence`) {
                    adoptionDelta -= 8; coachKey = `coach_r1_evidence`;
                } else {
                    adoptionDelta -= 12; sustainDelta -= 6; coachKey = `coach_r1_none`;
                }

                // Honesty: willingness to fix adoption rather than re-prove the science.
                if (d.honesty >= 60) { adoptionDelta += 8; }
                else if (d.honesty <= 25) { adoptionDelta -= 8; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.barrier === this.TRUE_BARRIER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Package the evidence + choose opinion-leaders (Common Errors 1 & 2).
                const peer = d.peer, expert = d.expert, manager = d.manager;
                wte = peer + expert + manager;

                // Framing: local data feedback and clinical narrative win; mandate hardens
                // resistance; an email does nothing.
                switch (d.framing) {
                    case `localdata`: adoptionDelta += 12; sustainDelta += 5; coachKey = `coach_r2_localdata`; break;
                    case `narrative`: adoptionDelta += 8; sustainDelta += 2; coachKey = `coach_r2_narrative`; break;
                    case `mandate`: adoptionDelta -= 6; sustainDelta -= 4; paperDelta += 6; coachKey = `coach_r2_mandate`; break;
                    case `email`: adoptionDelta -= 4; coachKey = `coach_r2_email`; break;
                }

                // Opinion-leaders: the trusted night-shift peer shifts practice more than the
                // distant expert. Expert-only = Common Error 2 (the professor at the night shift).
                const peerLead = peer >= expert && peer >= manager;
                if (expert >= 0.4 && peer <= 0.1) {
                    adoptionDelta -= 10; coachKey = `coach_r2_expertonly`;
                } else if (peerLead && peer >= 0.25 && expert > 0 && manager > 0) {
                    adoptionDelta += 14; sustainDelta += 6; coachKey = `coach_r2_balanced`;
                } else if (peerLead) {
                    adoptionDelta += 9; sustainDelta += 3;
                } else if (manager >= 0.4) {
                    adoptionDelta -= 4; paperDelta += 4; coachKey = `coach_r2_manageronly`;
                } else {
                    adoptionDelta += 3;
                }

                // Artefact: e-prompt + card embeds the bundle in the workflow; commissioning a
                // fresh evidence review is re-proving the science (Common Error 1).
                switch (d.artefact) {
                    case `eprompt`: spend += 90; adoptionDelta += 8; sustainDelta += 6; break;
                    case `card`: spend += 25; adoptionDelta += 4; sustainDelta += 1; break;
                    case `study`: spend += 60; adoptionDelta -= 8; sustainDelta -= 2; coachKey = `coach_r2_study`; break;
                }

                summaryKey = (peerLead && d.framing !== `mandate` && d.framing !== `email` && d.artefact !== `study`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Adapt to context & sequence the rollout (Common Errors 3 & 4).
                // Sequencing: pilot-and-spread beats a uniform big-bang mandate.
                switch (d.sequence) {
                    case `pilot`: adoptionDelta += 12; sustainDelta += 8; coachKey = `coach_r3_pilot`; break;
                    case `bigbang`: adoptionDelta -= 8; sustainDelta -= 4; paperDelta += 5; coachKey = `coach_r3_bigbang`; break;
                    case `edfirst`: adoptionDelta -= 4; sustainDelta -= 2; coachKey = `coach_r3_edfirst`; break;
                }

                // Fidelity vs local fit: flex the how, protect the clinical what.
                switch (d.fidelity) {
                    case `flexhow`: adoptionDelta += 12; sustainDelta += 4; coachKey = (d.sequence === `pilot`) ? `coach_r3_contextfit` : coachKey; break;
                    case `rigid`: adoptionDelta -= 10; paperDelta += 8; coachKey = `coach_r3_rigid`; break;
                    case `anything`: adoptionDelta -= 6; sustainDelta -= 6; coachKey = `coach_r3_anything`; break;
                }

                // Feedback loops: weekly audit + correction is the engine of sustainable adoption.
                spend += d.feedback;
                if (d.feedback >= 25) { sustainDelta += 10; adoptionDelta += 5; }
                else if (d.feedback >= 10) { sustainDelta += 4; adoptionDelta += 2; }
                else { sustainDelta -= 6; coachKey = `coach_r3_nofeedback`; }

                // Protecting frontline / night-shift time. Mandate without protected time = paper.
                if (d.protect >= 60) { adoptionDelta += 8; sustainDelta += 4; }
                else if (d.protect <= 25) { adoptionDelta -= 8; paperDelta += 5; coachKey = `coach_r3_noprotect`; }

                summaryKey = (d.sequence === `pilot` && d.fidelity === `flexhow`) ? `sum_r3_good` : (d.fidelity === `rigid` || d.sequence === `bigbang` ? `sum_r3_paper` : `sum_r3_weak`);
            } else if (round === 4) {
                // Embed, measure & defend (Common Error 5 + coercion limits).
                switch (d.measure) {
                    case `leadlag`: adoptionDelta += 8; sustainDelta += 12; coachKey = `coach_r4_leadlag`; break;
                    case `lagonly`: sustainDelta -= 2; paperDelta += 4; coachKey = `coach_r4_lagonly`; break;
                    case `launch`: sustainDelta -= 10; paperDelta += 6; coachKey = `coach_r4_launch`; break;
                }

                // Ownership after handover — the difference between a project and a changed practice.
                switch (d.ownership) {
                    case `named`: sustainDelta += 14; adoptionDelta += 4; break;
                    case `champion`: sustainDelta -= 6; coachKey = `coach_r4_champion`; break;
                    case `nobody`: sustainDelta -= 14; coachKey = `coach_r4_nobody`; break;
                }

                // The board's challenge: real adoption vs a paper trajectory.
                switch (d.board) {
                    case `honest`: adoptionDelta += 10; sustainDelta += 6; coachKey = (d.ownership === `named`) ? `coach_r4_honest` : coachKey; break;
                    case `coerce`: paperDelta += 14; adoptionDelta -= 8; sustainDelta -= 8; coachKey = `coach_r4_coerce`; break;
                    case `declare`: paperDelta += 8; sustainDelta -= 10; coachKey = `coach_r4_declare`; break;
                }

                // Conviction nudges adoption.
                adoptionDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.measure === `leadlag` && d.ownership === `named` && d.board === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round((ds.budgetUsed + spend)));
            ds.championUsed = Math.round((ds.championUsed + wte) * 100) / 100;

            // Adoption quality (genuine belief) and sustainability move on their deltas.
            ds.adoption = Math.max(0, Math.min(100, ds.adoption + adoptionDelta));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustainDelta));

            // Compliance is driven by genuine adoption PLUS any coerced/paper gains. Paper gains
            // lift the headline number but not real adoption — and they decay sustainability.
            const adoptionGain = Math.max(0, adoptionDelta) * 0.85;
            const paperGain = paperDelta * 0.9;
            let complianceDelta = adoptionGain + paperGain + Math.min(0, adoptionDelta) * 0.4;
            ds.compliance = Math.max(0, Math.min(100, ds.compliance + complianceDelta));

            // Flag paper compliance: headline rising while genuine adoption lags badly.
            if (paperDelta >= 8 && ds.adoption < ds.compliance - 20) ds.paperCompliance = true;

            ds.complianceHistory.push(Math.round(ds.compliance));
            ds.adoptionHistory.push(Math.round(ds.adoption));
            ds.sustainHistory.push(Math.round(ds.sustain));

            if (round === this.ROUNDS.length && ds.compliance < this.TARGET_COMPLIANCE) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                compliance: Math.round(ds.compliance),
                complianceDelta: Math.round(complianceDelta),
                adoption: Math.round(ds.adoption),
                adoptionDelta: Math.round(adoptionDelta),
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustainDelta),
                championUsed: ds.championUsed,
                budgetUsed: ds.budgetUsed,
                paperCompliance: ds.paperCompliance,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

