            // Protect slider readout.
            const pr = document.getElementById(`protectInput`);
            const prReadout = document.getElementById(`protectReadout`);
            if (pr && prReadout) {
                prReadout.textContent = pr.value;
                pr.addEventListener(`input`, function() { prReadout.textContent = pr.value; });
            }

            // Champion-time (WTE) live total.
            const wteIds = [`peerInput`, `expertInput`, `managerInput`];
            const wteReadout = document.getElementById(`wteReadout`);
            const recompute = function() {
                let total = 0;
                wteIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (wteReadout) wteReadout.textContent = total.toFixed(2);
                const bar = document.querySelector(`.evidencesim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.WTE_CAP) > 0.001) ? `#c0392b` : ``;
            };
            wteIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

