        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.complianceHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                evidenceChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.complianceHistory },
                        { data: ds.adoptionHistory },
                        { data: ds.sustainHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period for
        // the reporting/grading layer. Weights copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var c = Math.round(ds.compliance || 0), a = Math.round(ds.adoption || 0), s = Math.round(ds.sustain || 0);
            return Math.max(0, Math.min(100, Math.round(Math.min(100, c) * 0.35 + a * 0.35 + s * 0.30)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const compliance = Math.round(ds.compliance);
            const adoption = Math.round(ds.adoption);
            const sustain = Math.round(ds.sustain);

            const hitTarget = compliance >= this.TARGET_COMPLIANCE;
            const realAdoption = adoption >= 60 && sustain >= 55;
            const paper = ds.paperCompliance || (hitTarget && adoption < 45);
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_stalled`;
            if (hitTarget && realAdoption && composite >= 72) performanceKey = `grade_embedded`;
            else if (hitTarget && realAdoption) performanceKey = `grade_credible`;
            else if (hitTarget && paper) performanceKey = `grade_paper`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (compliance > this.START_COMPLIANCE + 15) performanceKey = `grade_improving`;
            const performance = T(performanceKey);

            const insights = [];
            if (hitTarget && realAdoption) insights.push(window.mySimulation.t(`insight_embedded`));
            else if (hitTarget && paper) insights.push(window.mySimulation.t(`insight_paper`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (sustain < 45) insights.push(window.mySimulation.t(`insight_decay`));
            if (adoption < 45) insights.push(window.mySimulation.t(`insight_lowadoption`));
            if (compliance >= this.NATIONAL_TARGET) insights.push(window.mySimulation.t(`insight_national`));
            if (hitTarget && realAdoption && sustain >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                compliance: compliance,
                adoption: adoption,
                sustain: sustain,
                hitTarget: hitTarget,
                paper: paper,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var met = !!s.hitTarget;
            var badge = met
                ? '<span class="ev-cm-badge ev-cm-yes">' + T('cm_target_met') + '</span>'
                : '<span class="ev-cm-badge ev-cm-no">' + T('cm_target_missed') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="ev-cm-metric"><span class="ev-cm-mv">' + Math.round(s.compliance||0) + '%</span><span class="ev-cm-ml">' + T('cm_m_compliance') + '</span></div>'
                + '<div class="ev-cm-metric"><span class="ev-cm-mv">' + Math.round(s.adoption||0) + '</span><span class="ev-cm-ml">' + T('cm_m_adoption') + '</span></div>'
                + '<div class="ev-cm-metric"><span class="ev-cm-mv">' + Math.round(s.sustain||0) + '</span><span class="ev-cm-ml">' + T('cm_m_sustain') + '</span></div>';
            return ''
                + '<div class="ev-completion">'
                +   '<div class="ev-cm-head">'
                +     '<div class="ev-cm-score">' + score + '<span class="ev-cm-score-max">/100</span></div>'
                +     '<div class="ev-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="ev-cm-metrics">' + metrics + '</div>'
                +   '<div class="ev-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="ev-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.paperCompliance) return window.mySimulation.t(`hint_paper`);
            if (ds.sustain < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sustain`);
            if (ds.adoption < 35) return window.mySimulation.t(`hint_adoption`);
            if (state.currentPeriod >= 3 && ds.compliance < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.compliance >= this.TARGET_COMPLIANCE && ds.adoption >= 60 && ds.sustain >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

